<template>
  <section class="xq-card" :class="{ 'xq-dark': dark }" aria-labelledby="xueqiu-title">
    <header class="xq-heading"><div><h2 id="xueqiu-title"><span class="xq-logo" aria-hidden="true"><img :src="sourceIcon" width="26" height="26" alt="" referrerpolicy="no-referrer" /></span>雪球热帖</h2></div><div class="xq-heading-meta"><span role="status">{{ status }}</span><a href="https://xueqiu.com/" target="_blank" rel="noopener noreferrer" title="访问雪球" aria-label="访问雪球">↗</a></div></header>
      <ol v-if="visible.length" class="xq-list"><li v-for="(post,index) in visible" :key="post.url"><a :href="post.url" target="_blank" rel="noopener noreferrer"><span class="xq-rank" :class="{ top:index<3 }">{{ post.rank }}</span><div class="xq-copy"><h3>{{ post.title }}</h3><div class="xq-meta"><span v-if="post.author" class="xq-node">{{ post.author }}</span><span>回复 {{ formatCount(post.replies) }}</span><span v-if="post.likes">赞 {{ formatCount(post.likes) }}</span></div></div><span class="xq-arrow" aria-hidden="true">↗</span></a></li></ol>
      <div v-else class="xq-empty">{{ loading ? '正在加载 雪球热帖…' : '雪球内容暂未更新，请稍后重试。' }}<button v-if="!loading" type="button" @click="load">重试</button></div>
      <footer class="xq-footer"><span>来自雪球社区 · 每3小时更新</span><button v-if="items.length>6" type="button" data-source-more :aria-expanded="showAll" @click="showAll=!showAll">{{ showAll ? '收起帖子 ↑' : '更多帖子 ↓' }}</button></footer>
    </section>
</template>
<script>
import { officialSourceIcon } from "../utils/source-icons.mjs";
export default {
  name:'XueqiuHot', props:{dark:Boolean},
  data:()=>({sourceIcon:officialSourceIcon('xueqiu'),items:[],updatedAt:'',loading:false,error:false,showAll:false,controller:null}),
  computed:{
    visible(){return this.items.slice(0,this.showAll?30:6);},
    status(){if(this.error&&this.items.length)return '刷新失败 · 显示缓存';const d=new Date(this.updatedAt);if(!Number.isFinite(d.getTime()))return '等待更新';return d.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}
  },
  mounted(){this.load();},beforeUnmount(){this.controller?.abort();},
  methods:{
    validUrl(post){try{const url=new URL(post.url);return url.origin==='https://xueqiu.com'&&url.pathname.split('/').filter(Boolean).length>=2;}catch{return false;}},
    formatCount(value){const n=Number(value)||0;return n>=10000?`${(n/10000).toFixed(1)}万`:String(n);},
    accept(data){if(!Array.isArray(data?.items)||!Number.isFinite(Date.parse(data.updatedAt)))throw Error('invalid data');const items=data.items.filter(t=>Number.isInteger(t.rank)&&t.rank>0&&typeof t.title==='string'&&this.validUrl(t)).slice(0,30);if(!items.length)throw Error('empty data');this.items=items;this.updatedAt=data.updatedAt;},
    async load(){this.loading=true;this.error=false;try{const data=JSON.parse(localStorage.getItem('navigation-xueqiu-v1'));if(data)this.accept(data);}catch{/* optional cache */}this.controller=new AbortController();const timeout=setTimeout(()=>this.controller.abort(),12000);try{const r=await fetch(`${process.env.BASE_URL}xueqiu-hot.json`,{cache:'no-cache',signal:this.controller.signal});if(!r.ok)throw Error('request failed');const data=await r.json();this.accept(data);try{localStorage.setItem('navigation-xueqiu-v1',JSON.stringify(data));}catch{/* optional storage */}}catch{this.error=true;}finally{clearTimeout(timeout);this.loading=false;}}
  }
};
</script>
<style scoped>
.xq-card{--v-text:#26364c;--v-muted:#7b8799;--v-line:rgba(105,128,160,.15);border:1px solid var(--v-line);border-radius:18px;background:rgba(255,255,255,.86);color:var(--v-text);padding:20px 20px 0;box-sizing:border-box;overflow:hidden;box-shadow:0 6px 24px rgba(37,68,109,.04)}.xq-dark{--v-text:#e2e9f4;--v-muted:#95a3b9;--v-line:rgba(145,164,194,.17);background:rgba(24,31,45,.92)}.xq-heading{display:flex;flex-wrap:nowrap;align-items:center;justify-content:space-between;gap:8px;padding-bottom:18px}.xq-heading>div:first-child{min-width:0;flex:1 1 auto}.xq-heading-meta{flex:0 0 auto;display:flex;align-items:center;gap:6px;font-size:10px;line-height:1.4;color:var(--v-muted);margin-inline-start:auto;white-space:nowrap}.xq-heading-meta a{color:inherit;text-decoration:none;flex-shrink:0}.xq-heading h2{display:flex;align-items:center;gap:8px;margin:0;font-size:18px;line-height:1.5;min-width:0;overflow:hidden;white-space:nowrap}.xq-logo{display:grid;place-items:center;width:32px;height:32px;border-radius:9px;background:#f0f0f0;overflow:hidden}.xq-logo img{display:block}.xq-card button{font:inherit;font-size:12px;border:0;background:transparent;color:var(--v-muted);padding:6px 9px;border-radius:7px;cursor:pointer;flex-shrink:0}.xq-card button:hover{color:#3f8ce8;background:rgba(63,140,232,.08)}.xq-card a:focus-visible,.xq-card button:focus-visible{outline:2px solid #3f8ce8;outline-offset:2px}.xq-list{list-style:none;padding:0;margin:0}.xq-list li{min-width:0}.xq-list a{display:flex;align-items:center;gap:10px;padding:16px 3px;text-decoration:none;color:inherit;border-bottom:1px solid var(--v-line);border-radius:7px;min-height:88px;box-sizing:border-box}.xq-list a:hover{background:rgba(127,145,171,.06)}.xq-rank{font-size:17px;font-weight:700;color:#a3adbb}.xq-rank.top{color:#3f8ce8}.xq-copy{min-width:0;flex:1}.xq-copy h3{font-size:13px;line-height:1.65;font-weight:500;margin:0;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.xq-meta{display:flex;gap:8px;flex-wrap:wrap;font-size:10px;color:var(--v-muted);margin-top:8px;align-items:center;overflow-wrap:anywhere}.xq-node{padding:2px 5px;background:rgba(127,145,171,.09);border-radius:4px}.xq-arrow{font-size:14px;color:var(--v-muted)}.xq-footer{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 0;font-size:10px;color:var(--v-muted);line-height:1.7}.xq-empty{text-align:center;color:var(--v-muted);padding:24px 0;font-size:12px}@media(max-width:700px){.xq-card{padding:16px 16px 0}}
</style>
